import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"49、【革】 离下兑上","description":"周易尚氏学 - 49、【革】 离下兑上","frontmatter":{"title":"49、【革】 离下兑上","description":"周易尚氏学 - 49、【革】 离下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/054.md","filePath":"zh/classics/shangshi/054.md"}'),s={name:"zh/classics/shangshi/054.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_49、【革】-离下兑上" tabindex="-1">49、【革】 离下兑上 <a class="header-anchor" href="#_49、【革】-离下兑上" aria-label="Permalink to “49、【革】 离下兑上”">​</a></h1><p>革改也。言水火更代用事也。离为日贞己。故曰己日。己日谓二。二离主爻。承阳应五。故曰己日乃孚。王弼等谓即日不孚、己日乃孚。训己为过往。不辞甚矣。顾炎武日知录。谓朱子发读为戊己之己。当从之。按虞氏注云。离为日。孚谓坎。四动体离。故己日乃孚。是虞氏亦以离为己日。读为戊己之己明甚。而非始于朱子发。元亨利贞。即春夏秋冬。象传所谓四时也。四时更代。乃革之最大者。卦巽居春夏之交。离为夏。兑为秋。乾为冬。故曰元亨利贞。纯取革义。辞虽与乾象同。义则殊也。</p><p>彖曰。革。水火相息。二女同居。其志不相得。曰革。己日乃孚。革而信之。文明以说。大亨以正。革而当。其悔乃亡。天地革而四时成。汤武革命。顺乎天而应乎人。革之时大矣哉。</p><p>息长也。言更代用事也。但兑离皆阴卦。易之道阴遇阳。阳遇阴方志得。若阴遇阴。阳遇阳。则为敌矣。中孕六三曰得敌。艮彖曰敌应。是也。故其志不相得。巽为志。二至上正反巽。故不相得。己中央土。仁义礼智信。信亦隶中央。故曰己日乃孚。革而信之。信故无悔。四时相代实相革。期无或爽。信也。汤武革命。天人皆应。亦信也。不信则不能革。故时之所关甚大。此其义也。</p><p>象曰。泽中有火。革。君子以治历明时。</p><p>历者日月星辰之所历。识其处以定四时。书所谓敬授民时。大戴记之夏小正。小戴记之月令皆历也。卦上兑为月。下离为日。乾为寒。离为暑。兑雨巽风皆备。故君子法之。以治历明时。</p><p>初九。巩用黄牛之革。</p><p>离外则故曰巩。巩固也。离为牛。左传曰纯离为牛。离六二云黄离。故曰黄牛。乃虞翻则谓离无牛象。乾宝谓离父本坤。故曰黄牛。皆非也。离外坚为甲故为革。革皮去毛者也。固莫团于牛革。言初当勿用之时。不可妄动。宜固守也。牛革所以喻其固也。</p><h3 id="象曰。巩用黄牛。不可以有为也。" tabindex="-1">象曰。巩用黄牛。不可以有为也。 <a class="header-anchor" href="#象曰。巩用黄牛。不可以有为也。" aria-label="Permalink to “象曰。巩用黄牛。不可以有为也。”">​</a></h3><p>初潜龙勿用。故不可以有为。又上无应。即不信也。不信即不可革。</p><p>六二。己日乃革之。征吉。无咎。</p><p>二离主爻。离贞己。故曰己。二有应。故曰己日乃革。二遇阳。故拉吉而无咎也。按二为日中。王弼以过往诂己日。故决知其非是。</p><h3 id="象曰。已日乃革之。行有嘉也。" tabindex="-1">象曰。已日乃革之。行有嘉也。 <a class="header-anchor" href="#象曰。已日乃革之。行有嘉也。" aria-label="Permalink to “象曰。已日乃革之。行有嘉也。”">​</a></h3><p>乾为嘉。行有嘉。谓二征则遇阳 遇阳故人。</p><p>九三。征凶。贞厉。革言三就。有孚</p><p>三临重阳。阳遇阳则窒。故征凶。卜问厉也。然三应在上。上兑为言。而兑为毁折。故曰革言。就即也。遇也。革言三就有孚者。言三虽得敌。不能应上。若上六即三。则甚顺利而有孚也。兑为言。乾亦为言。言多故曰三就。又三在三爻。损六三云。三人行。需上六云三人来。皆以在三交。取数于三。三就者三遇也。谓革言来之多也。有孚者上孚于三也。易理失传。旧解于征凶之故。莫有明者。岂知征凶贞厉。谓阳遇阳。下二句谓上应三。义不相属也。</p><h3 id="象曰。革言三就。又何之矣。" tabindex="-1">象曰。革言三就。又何之矣。 <a class="header-anchor" href="#象曰。革言三就。又何之矣。" aria-label="Permalink to “象曰。革言三就。又何之矣。”">​</a></h3><p>之往也。又何之者。言上六即三。不必他往也。盖革言日至则孚者众。而事已审。革之而已。勿再犹豫不定也。</p><p>九四。悔亡。有孚。改命吉。</p><p>四失位。宜有悔。无应予则无孚。然九四居乾之中。乾为信。故无悔而有孚。巽为命。四至上巽覆。是改命也。易林人畜之夬也。太子扶苏出于远郊。佞幸成邪。改命生忧。即以夬上兑为改命本此也。改命则革也。盖初以时未至而固守。二孚于天时。三孚于人事。至四遂实行改革矣。乾四云或跃在渊。与此理同也。自覆象失传。旧解皆以四变阴成既济为改命。既济者终正。何吉之有哉。非也。</p><h3 id="象曰。改命之吉。信志也。" tabindex="-1">象曰。改命之吉。信志也。 <a class="header-anchor" href="#象曰。改命之吉。信志也。" aria-label="Permalink to “象曰。改命之吉。信志也。”">​</a></h3><p>巽为志。改命则实行革命。故曰伸志。言得行其志也。志行故吉。</p><p>九五。大人虎变。未占有孚</p><p>乾为大人为虎。大人虎变者。喻大人履九五之尊。威德诞敷。崇高巍焕。改易旧观。故曰虎变。下有应。故未占而有孚也。乾虎象失传。后惟茹敦和俞樾知之。虞翻以坤为虎。宋衷以兑为虎。皆非。</p><h3 id="象曰。大人虎变-其文炳也。" tabindex="-1">象曰。大人虎变，其文炳也。 <a class="header-anchor" href="#象曰。大人虎变-其文炳也。" aria-label="Permalink to “象曰。大人虎变，其文炳也。”">​</a></h3><p>五应二。二离为文。故其文炳。</p><p>上六。君子豹变。小人革面。征凶。居贞吉。</p><p>伏艮为君子。为豹。君子豹变者。谓革命后住命之动。皆得封拜而有茅土。尊显富贵。易世成名。故曰豹变。阴称小人。民为面。艮伏故革面。小人革面者。谓革命之后，除旧布新。小民皆改易其视向也。面向也。史记项羽本纪。马童面之。是也。上六当位，不宜动宜静。故征凶居吉。艮面象。易林遁之蒙云。云过吾面。以蒙坎为云。艮为面。虞氏谓面指四。非。</p><h3 id="象曰。君子豹变。其文蔚也。小人革面。顺以从君也。" tabindex="-1">象曰。君子豹变。其文蔚也。小人革面。顺以从君也。 <a class="header-anchor" href="#象曰。君子豹变。其文蔚也。小人革面。顺以从君也。" aria-label="Permalink to “象曰。君子豹变。其文蔚也。小人革面。顺以从君也。”">​</a></h3><p>下应三。离为文。面向也。故曰顺以从君。言下顺乾也。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
